# Schedule ingestion and building the factorial manifest ====

# Parses a wide binary schedule matrix (rows = candidate schedules, T_*h columns = 
# binary indicators 0/1) into a tidy list of numeric sampling times per schedule. 
# Extracts timestamps from column headers (e.g., "T_0.5h" -> 0.5) and maps each 
# row to a unique Schedule_Key combining its sampling density regime and cohort ID.
parse_binary_schedule_file <- function(file_path, family_name) {
  if (!file.exists(file_path)) {
    warning("File not found: ", file_path)
    return(data.frame())
  }
  raw <- read.csv(file_path, stringsAsFactors = FALSE, check.names = FALSE)
  time_cols <- grep("^T_.+h$", names(raw), value = TRUE)
  extracted_times <- as.numeric(sub("^T_(.+)h$", "\\1", time_cols))
  
  rows <- lapply(seq_len(nrow(raw)), function(i) {
    row_data  <- raw[i, ]
    sel_idx   <- which(as.numeric(row_data[time_cols]) == 1)
    sel_times <- sort(extracted_times[sel_idx])
    
    data.frame(
      Schedule_Family           = family_name,
      Sampling_Threshold        = as.character(row_data$DENSITY_REGIME),
      Cohort_Match_ID           = as.integer(row_data$COHORT),
      Number_of_Nominal_Samples = length(sel_times),
      Schedule_ID               = paste0(family_name, "_", row_data$DENSITY_REGIME, "_cohort_", sprintf("%02d", row_data$COHORT)),
      Schedule_Times            = paste(sel_times, collapse = ";"),
      Evaluation_Engine         = "Direct_NCA",
      Analysis_Type             = "Primary",
      stringsAsFactors          = FALSE
    )
  })
  bind_rows(rows)
}

sched_pure_ga    <- parse_binary_schedule_file(config$file_pure_ga,       "Pure_GA")
sched_pchip49    <- parse_binary_schedule_file(config$file_pchip49,       "PCHIP_49")
