write.csv(master_schedule_index, file.path(table_dir, "01_master_schedule_index.csv"), row.names = FALSE)
message(sprintf(">> Ingested %d schedule configurations.", nrow(master_schedule_index)))

# Data ingestion and NCA engine with extrapolation ====
raw_pk <- read.csv(config$patient_file, stringsAsFactors = FALSE)
if ("NEW_ID" %in% names(raw_pk)) raw_pk$ID <- raw_pk$NEW_ID

patient_data <- raw_pk %>%
  filter(TIME >= config$time_range[1], TIME <= config$time_range[2], DV > 0) %>%
  select(ID, TIME, DV) %>%
  mutate(DOSE_UG = config$dose_ug) %>%
  arrange(ID, TIME)

# Computes standard non-compartmental analysis (NCA) parameters (Cmax, Tmax, 
# AUClast, Cl_pred, Vz_pred, HL_Lambda_z) via ncappc for a given schedule dataset.
# Suppresses diagnostic messages during batch runs and standardizes column names.
run_direct_nca <- function(sub_df) {
  if (!any(round(sub_df$TIME, 6) == 0)) {
    t0 <- data.frame(ID = unique(sub_df$ID), TIME = 0, DV = 0, DOSE_UG = config$dose_ug)
    sub_df <- bind_rows(sub_df, t0) %>% arrange(ID, TIME)
  }
  
  fit <- suppressWarnings(suppressMessages(
    ncappc::ncappc(
      obsFile       = sub_df, 
      concNmObs     = "DV", 
      timeNmObs     = "TIME", 
      idNmObs       = "ID", 
      doseAmtNm     = "DOSE_UG",
      adminType     = "extravascular", 
      doseType      = "ns", 
      method        = "linearup-logdown", # Use linear-up/log-down trapezoidal rule for AUC integration
      onlyNCA       = TRUE,  # allow terminal elimination rate (lambda_z) estimation from >= 2 terminal points (adjusted R^2 >= 0)
      extrapolate   = TRUE, # Populates Cl_pred and Vz_pred via log-linear regression
      noPlot        = TRUE, 
      printOut      = FALSE, 
      evid          = FALSE
    )
  ))
  
  res <- as.data.frame(fit$ncaOutput)
  
  data.frame(
    ID       = as.integer(res$ID),
    Cmax     = as.numeric(res$Cmax),
    Tmax     = as.numeric(res$Tmax),
    AUC      = as.numeric(res$AUClast),
    CL_F     = as.numeric(res$Cl_pred),     # Extrapolated parameter
    Vz_F     = as.numeric(res$Vz_pred),     # Extrapolated parameter
    T_half   = as.numeric(res$HL_Lambda_z),
    Lambda_z = as.numeric(res$Lambda_z),
    stringsAsFactors = FALSE
  )
}

# Reconstructs dense concentration-time profiles from sparse observations using PCHIP.
# Anchors profiles at (t = 0, DV = 0) if t = 0 is not explicitly sampled.
# Interpolates within the observed time span [0, max_x] via pracma::pchip().
# For grid points beyond the last observed sample (out_t), applies linear 
# extrapolation using the slope of the final two observed points and clamps 
# negative concentrations at zero before passing to standard NCA.
run_pchip_nca <- function(sub_df, full_grid) {
  subj_list <- split(sub_df, sub_df$ID)
  reconstructed_rows <- lapply(subj_list, function(sdf) {
    x_obs <- sdf$TIME
    y_obs <- sdf$DV
    if (!any(round(x_obs, 6) == 0)) {
      x_obs <- c(0, x_obs)
      y_obs <- c(0, y_obs)
    }
    ord   <- order(x_obs)
    x_obs <- x_obs[ord]; y_obs <- y_obs[ord]
    n     <- length(x_obs)
    
    max_x <- max(x_obs)
    in_t  <- full_grid[full_grid <= max_x]
    out_t <- full_grid[full_grid > max_x]
    
    in_y <- tryCatch(pracma::pchip(x_obs, y_obs, in_t), error = function(e) rep(NA, length(in_t)))
    out_y <- numeric(0)
    if (length(out_t) > 0) {
      slope <- (y_obs[n] - y_obs[n - 1]) / (x_obs[n] - x_obs[n - 1])
      out_y <- y_obs[n] + slope * (out_t - x_obs[n])
    }
    full_y <- pmax(c(in_y, out_y), 0)
    data.frame(ID = sdf$ID[1], TIME = full_grid, DV = full_y, DOSE_UG = config$dose_ug)
  })
  recon_df <- bind_rows(reconstructed_rows) %>% arrange(ID, TIME)
  run_direct_nca(recon_df)
}

# Pre-compute rich reference NCA
# Establish ground-truth NCA parameters on the full, densely sampled simulated 
# dataset (all 49 timepoints across N = 1,000 subjects) to serve as the reference 
# benchmark for sparse-schedule estimation error
message(">> Computing rich reference NCA with extrapolation enabled...")
