  meta  <- master_schedule_index[i, ]
  times <- as.numeric(strsplit(meta$Schedule_Times, ";")[[1]])
  sub_d <- patient_data %>% filter(round(TIME, 6) %in% round(times, 6))
  
  if (i %% 5 == 0 || i == 1 || i == n_sched) {
