    mutate(
      Schedule_ID               = meta$Schedule_ID,
      Schedule_Family           = meta$Schedule_Family,
      Sampling_Threshold        = meta$Sampling_Threshold,
      Cohort_Match_ID           = meta$Cohort_Match_ID,
      Number_of_Nominal_Samples = meta$Number_of_Nominal_Samples,
      Evaluation_Engine         = meta$Evaluation_Engine,
      Analysis_Type             = meta$Analysis_Type
    )
}

subject_nca_all <- bind_rows(evaluation_results)

# Error computation and aggregation (both percentage and physical units) ====

message(">> Computing subject-level errors, physical MAE, and summary metrics...")
metrics_list <- c("AUC", "Cmax", "Tmax", "CL_F", "Vz_F", "T_half")
true_long <- true_reference %>%
  select(ID, all_of(metrics_list)) %>%
  pivot_longer(cols = all_of(metrics_list), names_to = "Metric", values_to = "Reference")

subject_errors <- subject_nca_all %>%
  pivot_longer(cols = all_of(metrics_list), names_to = "Metric", values_to = "Estimate") %>%
  left_join(true_long, by = c("ID", "Metric")) %>%
  mutate(
    Is_Estimable   = is.finite(Estimate) & is.finite(Reference),
    Raw_Error      = if_else(Is_Estimable, Estimate - Reference, NA_real_),
    Absolute_Error = abs(Raw_Error),
    Squared_Error  = Raw_Error^2,
    PE             = if_else(Is_Estimable, (Estimate - Reference) / Reference * 100, NA_real_),
    APE            = abs(PE),
    SPE            = PE^2
  )

saveRDS(subject_errors, file.path(table_dir, "09_subject_errors_long.rds"))

schedule_level_summary <- subject_errors %>%
  group_by(Schedule_Family, Sampling_Threshold, Number_of_Nominal_Samples, 
           Schedule_ID, Cohort_Match_ID, Evaluation_Engine, Analysis_Type, Metric) %>%
  summarise(
    N_total          = n(),
    N_estimable      = sum(Is_Estimable),
    Nonestimable_pct = 100 * (N_total - N_estimable) / N_total,
    # Percentage Metrics
    MPE              = mean(PE[Is_Estimable], na.rm = TRUE),
    abs_MPE          = abs(MPE),
    MAPE             = mean(APE[Is_Estimable], na.rm = TRUE),
    RMSPE            = sqrt(mean(SPE[Is_Estimable], na.rm = TRUE)),
    # Physical Unit Metrics (Hours for Tmax, mg/L for Cmax)
    MAE              = mean(Absolute_Error[Is_Estimable], na.rm = TRUE),
    RMSE             = sqrt(mean(Squared_Error[Is_Estimable], na.rm = TRUE)),
    .groups          = "drop"
  )

write.csv(schedule_level_summary, file.path(table_dir, "10_schedule_level_error_summary.csv"), row.names = FALSE)

# Statistical tests ====

finite_vals <- function(x) as.numeric(x[is.finite(x)])

# Computes a two-sided 95% percentile bootstrap confidence interval for the 
# mean of paired differences (d). Filters out non-finite values and requires 
# at least 2 valid observations; defaults to 20,000 resamples with replacement.
bootstrap_ci <- function(d, reps = 20000L) {
  d <- finite_vals(d)
  if (length(d) < 2) return(c(NA_real_, NA_real_))
  vals <- replicate(reps, mean(sample(d, length(d), replace = TRUE)))
  unname(stats::quantile(vals, c(0.025, 0.975), na.rm = TRUE))
}

# Performs an exact two-sided paired sign-flip permutation test on paired 
# differences (d). Rather than Monte Carlo sampling, enumerates all 2^n 
# possible sign assignments (e.g., 2^10 = 1,024 permutations across the 10 
# matched subset cohorts) via bit-masking (intToBits) to compute the exact 
# p-value. A small tolerance (1e-12) prevents floating-point rounding errors 
# when comparing permuted statistics against the observed |mean(d)|.
exact_sign_flip <- function(d) {
  d <- finite_vals(d)
  n <- length(d)
  if (n == 0) return(NA_real_)
  obs <- abs(mean(d))
  n_perm <- 2^n
  stats  <- numeric(n_perm)
  for (m in 0:(n_perm - 1)) {
    signs <- ifelse(as.logical(intToBits(m)[seq_len(n)]), 1, -1)
    stats[m + 1] <- abs(mean(d * signs))
  }
  mean(stats >= obs - 1e-12)
}

# Calculates the two-sample Kolmogorov-Smirnov (KS) supremum distance D = 
# sup_x |F_1(x) - F_2(x)| across the combined empirical cumulative distribution 
# functions (ECDFs) of vectors x and y.
ks_stat <- function(x, y) {
  x <- sort(finite_vals(x)); y <- sort(finite_vals(y))
  if (length(x) == 0 || length(y) == 0) return(NA_real_)
  grid <- sort(unique(c(x, y)))
  max(abs(stats::ecdf(x)(grid) - stats::ecdf(y)(grid)))
}

# Evaluates distributional differences between paired samples (x, y) using an 
# exact paired permutation KS test. Preserves cohort pairing by enumerating all 
# 2^n within-pair swaps via bit-masking (intToBits) and recalculating the KS D 
# statistic under each permutation to derive an exact two-sided p-value.
paired_perm_ks <- function(x, y) {
  ok <- is.finite(x) & is.finite(y)
  x <- x[ok]; y <- y[ok]; n <- length(x)
  if (n < 2) return(list(D = NA_real_, P = NA_real_))
  obs <- ks_stat(x, y)
  n_perm <- 2^n
  res <- numeric(n_perm)
  for (m in 0:(n_perm - 1)) {
    sw <- as.logical(intToBits(m)[seq_len(n)])
    res[m + 1] <- ks_stat(ifelse(sw, y, x), ifelse(sw, x, y))
  }
  list(D = obs, P = mean(res >= obs - 1e-12))
}

# Executes all paired statistical comparisons between two schedule arms (df_a vs. 
# df_b) matched by Cohort_Match_ID across each PK parameter (Metric). Computes 
# mean error differences (A - B), 95% bootstrap CIs, exact sign-flip permutation 
# p-values, paired Wilcoxon signed-rank p-values, and paired permutation KS tests. 
# Applies Holm-Bonferroni step-down adjustment across the 6 PK parameters within 
# each contrast to control the family-wise error rate.
run_paired_contrast <- function(df_a, df_b, label_a, label_b, outcome_col) {
  merged <- inner_join(df_a, df_b, by = c("Cohort_Match_ID", "Metric"), suffix = c("_A", "_B"))
  merged %>%
    group_by(Metric) %>%
    group_modify(function(d, k) {
      val_a <- d[[paste0(outcome_col, "_A")]]
      val_b <- d[[paste0(outcome_col, "_B")]]
      delta <- val_a - val_b
      ci    <- bootstrap_ci(delta, config$bootstrap_reps)
      p_ks  <- paired_perm_ks(val_a, val_b)
      
      data.frame(
        Group_A       = label_a, Group_B = label_b, Outcome = outcome_col,
        Mean_A        = mean(val_a, na.rm = TRUE), Mean_B = mean(val_b, na.rm = TRUE),
        Mean_Delta    = mean(delta, na.rm = TRUE), CI_Lower = ci[1], CI_Upper = ci[2],
        Perm_P        = exact_sign_flip(delta),
        Wilcox_P      = tryCatch(suppressWarnings(stats::wilcox.test(val_a, val_b, paired = TRUE)$p.value), error = function(e) NA_real_),
        KS_D          = p_ks$D, KS_Perm_P = p_ks$P, stringsAsFactors = FALSE
      )
    }) %>%
    ungroup() %>%
    mutate(Perm_P_Holm = stats::p.adjust(Perm_P, method = config$p_adjust_method))
}

# Execute hypothesis testing ====

message(">> Executing hypothesis tests across primary, sensitivity, and ablation designs...")

# Primary Benchmark Tests
primary_tests <- list()
for (reg in config$regimes) {
  p_ga    <- schedule_level_summary %>% filter(Schedule_Family == "Pure_GA", Sampling_Threshold == reg, Evaluation_Engine == "Direct_NCA")
  poped   <- schedule_level_summary %>% filter(Schedule_Family == "PopED",   Sampling_Threshold == reg, Evaluation_Engine == "Direct_NCA")
  pchip49 <- schedule_level_summary %>% filter(Schedule_Family == "PCHIP_49", Sampling_Threshold == reg, Evaluation_Engine == "Direct_NCA")
  
  primary_tests[[paste0(reg, "_mape")]]  <- bind_rows(
    run_paired_contrast(p_ga, poped,   "Pure_GA", "PopED",    "MAPE"),
    run_paired_contrast(p_ga, pchip49, "Pure_GA", "PCHIP_49", "MAPE")
  ) %>% mutate(Regime = reg)
  
  primary_tests[[paste0(reg, "_rmspe")]] <- bind_rows(
    run_paired_contrast(p_ga, poped,   "Pure_GA", "PopED",    "RMSPE"),
    run_paired_contrast(p_ga, pchip49, "Pure_GA", "PCHIP_49", "RMSPE")
  ) %>% mutate(Regime = reg)
}
write.csv(bind_rows(primary_tests), file.path(table_dir, "21_primary_benchmark_tests.csv"), row.names = FALSE)

# Sensitivity 1 Tests (Factorial Swap at N=7)
sens1_ga_direct <- schedule_level_summary %>% filter(Schedule_Family == "Pure_GA", Sampling_Threshold == "semi-sparse", Evaluation_Engine == "Direct_NCA")
sens1_ga_pchip  <- schedule_level_summary %>% filter(Schedule_Family == "Pure_GA", Sampling_Threshold == "semi-sparse", Evaluation_Engine == "PCHIP_Reconstruction")
sens1_p49_pchip <- schedule_level_summary %>% filter(Schedule_Family == "PCHIP_49", Sampling_Threshold == "semi-sparse", Evaluation_Engine == "PCHIP_Reconstruction")
sens1_p49_dir   <- schedule_level_summary %>% filter(Schedule_Family == "PCHIP_49", Sampling_Threshold == "semi-sparse", Evaluation_Engine == "Direct_NCA")

sens1_tests <- bind_rows(
  run_paired_contrast(sens1_ga_pchip, sens1_ga_direct, "PureGA_evalPCHIP", "PureGA_evalDirect", "MAPE"),
  run_paired_contrast(sens1_p49_dir,  sens1_p49_pchip,  "PCHIP49_evalDirect", "PCHIP49_evalPCHIP", "MAPE"),
  run_paired_contrast(sens1_ga_pchip, sens1_ga_direct, "PureGA_evalPCHIP", "PureGA_evalDirect", "RMSPE"),
  run_paired_contrast(sens1_p49_dir,  sens1_p49_pchip,  "PCHIP49_evalDirect", "PCHIP49_evalPCHIP", "RMSPE")
)
write.csv(sens1_tests, file.path(table_dir, "22_sensitivity1_factorial_swap_tests.csv"), row.names = FALSE)

# Sensitivity 2 Tests (PCHIP-15 vs PCHIP-49)
sens2_tests <- list()
for (reg in config$regimes) {
  p49 <- schedule_level_summary %>% filter(Schedule_Family == "PCHIP_49", Sampling_Threshold == reg, Evaluation_Engine == "Direct_NCA")
  p15 <- schedule_level_summary %>% filter(Schedule_Family == "PCHIP_15", Sampling_Threshold == reg, Evaluation_Engine == "Direct_NCA")
  sens2_tests[[reg]] <- bind_rows(
    run_paired_contrast(p15, p49, "PCHIP_15", "PCHIP_49", "MAPE"),
    run_paired_contrast(p15, p49, "PCHIP_15", "PCHIP_49", "RMSPE")
  ) %>% mutate(Regime = reg)
}
write.csv(bind_rows(sens2_tests), file.path(table_dir, "23_sensitivity2_pchip15_vs_pchip49_tests.csv"), row.names = FALSE)

# Objective Function Benchmark (Pure GA vs Tsuchiwata GA at N=7)
ga_semi  <- schedule_level_summary %>% filter(Schedule_Family == "Pure_GA",        Sampling_Threshold == "semi-sparse", Evaluation_Engine == "Direct_NCA")
tsu_semi <- schedule_level_summary %>% filter(Schedule_Family == "Tsuchiwata_GA",  Sampling_Threshold == "semi-sparse", Evaluation_Engine == "Direct_NCA")

ablation_tests <- bind_rows(
  run_paired_contrast(ga_semi, tsu_semi, "Pure_GA", "Tsuchiwata_GA", "MAPE"),
  run_paired_contrast(ga_semi, tsu_semi, "Pure_GA", "Tsuchiwata_GA", "RMSPE")
)
write.csv(ablation_tests, file.path(table_dir, "24_ablation_pure_ga_vs_tsuchiwata_tests.csv"), row.names = FALSE)

# Friedman Omnibus Testing ====
# Runs nonparametric Friedman rank-sum tests across matched cohorts (blocking 
# factor: Cohort_Match_ID) to test omnibus differences across the three primary 
# methods (Pure_GA, PopED, PCHIP_49) and across sampling intensities (sparse, 
# semi-sparse, intensive). Filters to complete blocks (n == 3 arms per cohort) 
# before testing and applies Holm-Bonferroni correction across family-level tests.

message(">> Computing Friedman Omnibus ANOVA tests...")

# Schedule Generation method Omnibus: Pure GA vs PopED vs PCHIP-49
friedman_method <- schedule_level_summary %>%
  filter(
    Schedule_Family %in% c("Pure_GA", "PopED", "PCHIP_49"),
    Evaluation_Engine == "Direct_NCA",
    Analysis_Type == "Primary"
  ) %>%
  group_by(Sampling_Threshold, Metric) %>%
  group_modify(function(d, k) {
    complete_cohorts <- d %>%
      count(Cohort_Match_ID) %>%
      filter(n == 3) %>%
      pull(Cohort_Match_ID)
    
    sub_d <- d %>% filter(Cohort_Match_ID %in% complete_cohorts)
    if (length(complete_cohorts) < 3) {
      return(data.frame(Outcome = c("MAPE", "RMSPE"), Q_Statistic = NA_real_, df = NA_real_, p_value = NA_real_))
    }
    
    fit_mape  <- tryCatch(stats::friedman.test(MAPE ~ Schedule_Family | Cohort_Match_ID, data = sub_d), error = function(e) NULL)
    fit_rmspe <- tryCatch(stats::friedman.test(RMSPE ~ Schedule_Family | Cohort_Match_ID, data = sub_d), error = function(e) NULL)
    
    data.frame(
      Outcome     = c("MAPE", "RMSPE"),
      Q_Statistic = c(if (is.null(fit_mape)) NA_real_ else unname(fit_mape$statistic),
                      if (is.null(fit_rmspe)) NA_real_ else unname(fit_rmspe$statistic)),
      df          = c(if (is.null(fit_mape)) NA_real_ else unname(fit_mape$parameter),
                      if (is.null(fit_rmspe)) NA_real_ else unname(fit_rmspe$parameter)),
      p_value     = c(if (is.null(fit_mape)) NA_real_ else fit_mape$p.value,
                      if (is.null(fit_rmspe)) NA_real_ else fit_rmspe$p.value),
      stringsAsFactors = FALSE
    )
  }) %>%
  ungroup() %>%
  mutate(p_adj_Holm = stats::p.adjust(p_value, method = "holm"))

write.csv(friedman_method, file.path(table_dir, "25_friedman_method_omnibus_tests.csv"), row.names = FALSE)

# Sampling Intensity Omnibus: 4 vs 7 vs 15 Samples
